/**  Cannot proceed: an upstream Artifact is RED, ERROR or itself blocked. */
"blocked" | 
/**  Runnable but still waiting: queued, or for upstream Artifacts not done yet. */
"waiting" | 
/**  Every eval is GREEN. */
"green";

